<style>
    .sales-target-page{--st-navy:#12223e;--st-blue:#315ca7;--st-blue-soft:#eaf0fb;--st-teal:#15917f;--st-amber:#d98b16;--st-red:#d95252;--st-border:#e4eaf2;--st-muted:#718096;color:#24344d;display:grid;gap:18px}.st-hero{background:linear-gradient(125deg,#152746 0%,#244b83 58%,#2d6b9a 100%);border-radius:18px;color:#fff;padding:26px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px;box-shadow:0 12px 30px rgba(22,49,86,.18);position:relative;overflow:hidden}.st-hero:after{content:"";position:absolute;width:240px;height:240px;border-radius:50%;border:38px solid rgba(255,255,255,.05);right:-55px;top:-100px}.st-hero-copy,.st-hero-actions{position:relative;z-index:1}.st-eyebrow{display:inline-flex;gap:7px;align-items:center;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#b9d7ff}.st-hero h1{font-size:27px;font-weight:800;margin:6px 0}.st-hero p{margin:0;color:#d5e2f5;max-width:680px}.st-hero-meta{display:flex;flex-wrap:wrap;gap:15px;margin-top:18px;font-size:11px;color:#d5e2f5}.st-hero-meta span{display:flex;align-items:center;gap:5px}.st-hero-meta strong{color:#fff}.st-hero-actions{display:flex;gap:9px;flex-shrink:0}.st-primary-button,.st-secondary-button{display:inline-flex;align-items:center;gap:7px;font-weight:750;border-radius:10px;padding:10px 15px}.st-primary-button{background:#fff;color:#244b83;border:0}.st-primary-button:hover{background:#f2f6fd;color:#18365e}.st-secondary-button{border:1px solid rgba(255,255,255,.4);color:#fff}.st-secondary-button:hover{background:rgba(255,255,255,.1);color:#fff}.st-filter-bar{background:#fff;border:1px solid var(--st-border);border-radius:14px;padding:14px 17px;display:flex;align-items:end;gap:15px;box-shadow:0 4px 16px rgba(31,55,90,.05)}.st-filter-heading{display:flex;align-items:center;gap:10px;margin-right:auto}.st-filter-heading>span{width:38px;height:38px;border-radius:10px;background:var(--st-blue-soft);color:var(--st-blue);display:grid;place-items:center;font-