tter-spacing:.05em;padding:10px;white-space:nowrap}.st-table tbody td{border-color:#edf0f5;padding:11px 10px;vertical-align:middle}.st-period{display:flex;align-items:center;gap:9px}.st-period-icon{width:32px;height:32px;border-radius:9px;background:#eef3fb;color:#315ca7;display:grid;place-items:center;font-size:15px}.st-period strong{display:block;color:#24344d;font-size:11px}.st-period small{color:#8a96a7;font-size:9px}.st-money{font-weight:750;color:#2d3d56;white-space:nowrap}.st-money.is-positive{color:#148266}.st-money.is-negative{color:#d04a55}.st-row-progress{display:flex;align-items:center;gap:8px;min-width:135px}.st-row-progress>div{height:6px;flex:1;background:#edf1f6;border-radius:99px;overflow:hidden}.st-row-progress>div span{display:block;height:100%;background:#315ca7;border-radius:inherit}.st-row-progress strong{font-size:10px;min-width:42px;text-align:right}.st-config{display:block;font-size:8px;color:#8b97a7;margin-top:2px}.st-action-button{width:30px;height:30px;border:1px solid #dce3ed;border-radius:8px;background:#fff;color:#486383}.st-action-button:hover{background:#eef3fb;color:#315ca7}.st-empty{text-align:center!important;color:#8793a5;padding:28px!important}.st-branch-panel[hidden]{display:none}.st-branch-name strong{display:block;color:#24344d}.st-branch-name small{color:#8a96a7}.st-modal{border:0;border-radius:16px;overflow:hidden}.st-modal .modal-header{padding:17px 20px;border-bottom:1px solid #e7ecf3}.st-modal-title{display:flex;align-items:center;gap:10px}.st-modal-title>span{width:40px;height:40px;border-radius:11px;background:#eaf0fb;color:#315ca7;display:grid;place-items:center;font-size:21px}.st-modal-title small{display:block;color:#7c8a9d;text-transform:uppercase;letter-spacing:.08em;font-size:8px;font-weight:800}.st-modal-title h5{font-size:16px;color:#172a48;font-weight:800}.st-modal .modal-body{padding:20px}.st-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.st-form-grid label{display:flex;flex-direction:column;gap:6px}.st-form-grid label.is-wide{grid-column:1/-1}.st-form-grid label b{color:#d04a55}.st-form-grid .form-control,.st-form-grid .form-select{border-color:#dbe3ee;min-height:42px;font-size:12px}.st-form-grid label>small{color:#8692a3;font-size:9px}.st-money-input{display:flex;border:1px solid #dbe3ee;border-radius:.375rem;overflow:hidden}.st-money-input>span{background:#f3f6fa;color:#5f6e82;padding:11px 12px;font-size:11px;font-weight:800;border-right:1px solid #dbe3ee}.st-money-input input{border:0!important;border-radius:0!important}.st-form-info{display:flex;gap:9px;background:#eef5ff;color:#4b668b;border-radius:10px;padding:11px 12px;font-size:10px;line-height:1.5;margin-top:16px}.st-form-info i{font-size:17px;color:#315ca7}.st-modal .modal-footer{border-top:1px solid #e7ecf3;padding:13px 20px}.st-save-button{background:#315ca7;color:#fff}.st-save-button:hover{background:#284e8e;color:#fff}.st-loading{opacity:.58;pointer-events:none}.st-error{background:#fff1f1;border:1px solid #f4cccc;color:#a53d45;border-radius:10px;padding:12px;font-size:11px}
